function result = response_fit(input_file, beam, options)
%RESPONSE_FIT Fit free vibration and reconstruct effective coupon modulus.
% beam.length_m: free length excluding the reinforced root transition.
% beam.width_m, beam.thickness_m: rectangular cross-section dimensions.
% beam.density_kg_m3: condition-specific mean apparent density, not bulk density.
% The input CSV is generated by tracking.py. Times are in seconds; a fixed
% displacement scale (pixels or metres) is sufficient for frequency/damping.
% The fit retains the original fixed-phase damped cosine approximation.
arguments
    input_file (1,1) string
    beam (1,1) struct
    options.StartTime_s (1,1) double = 0
    options.EndTime_s (1,1) double = Inf
    options.EquilibriumDisplacement (1,1) double = 0
    options.InitialGuess (1,2) double = [0.012, 500]
    options.OutputPrefix (1,1) string = ""
    options.ShowPlot (1,1) logical = true
end

names = {'length_m','width_m','thickness_m','density_kg_m3'};
for i = 1:numel(names)
    assert(isfield(beam,names{i}), 'Missing beam.%s', names{i});
    validateattributes(beam.(names{i}), {'numeric'}, {'scalar','finite','positive'});
end
data = readtable(input_file, 'VariableNamingRule', 'preserve');
assert(all(ismember({'time_s','tip_displacement_px','tracking_status'}, data.Properties.VariableNames)), ...
    'Expected tracking.py columns: time_s, tip_displacement_px, tracking_status.');
keep = data.time_s >= options.StartTime_s & data.time_s <= options.EndTime_s;
x = data.time_s(keep);
y = data.tip_displacement_px(keep) - options.EquilibriumDisplacement;
assert(numel(x) >= 10 && all(isfinite(x)) && all(isfinite(y)), ...
    'Select at least 10 valid samples; inspect missing detections before fitting.');
assert(all(string(data.tracking_status(keep)) == "accepted"), ...
    'Fit window contains flagged detections; inspect them before fitting.');
assert(all(diff(x) > 0), 'Time values must be strictly increasing.');
x = x - x(1);  % The first selected sample must be a displacement extremum.
C = y(1);     % Keep the sign; do not replace a negative extremum by max(y).
assert(abs(C) > eps && range(y) > eps, 'No resolvable oscillation in the selected window.');

% zeta is dimensionless; omega_n is the undamped natural frequency in rad/s.
model = fittype(@(zeta, omega_n, time) C .* exp(-zeta .* omega_n .* time) .* ...
    cos(omega_n .* sqrt(1-zeta.^2) .* time), ...
    'independent', 'time', 'coefficients', {'zeta','omega_n'});
[fitted, gof] = fit(x, y, model, 'StartPoint', options.InitialGuess, ...
    'Lower', [0, eps], 'Upper', [0.999, Inf]);

% Define dimensions before I: the original script used height before assignment.
A = beam.width_m * beam.thickness_m;
I = beam.width_m * beam.thickness_m^3 / 12;
mass_per_length = beam.density_kg_m3 * A;
E_eff = fitted.omega_n^2 * mass_per_length * beam.length_m^4 / (1.875^4 * I);
result = struct('damping_ratio', fitted.zeta, 'omega_n_rad_s', fitted.omega_n, ...
    'natural_frequency_hz', fitted.omega_n/(2*pi), ...
    'damped_frequency_hz', fitted.omega_n*sqrt(1-fitted.zeta^2)/(2*pi), ...
    'effective_modulus_pa', E_eff, 'r_squared', gof.rsquare, 'rmse_px', gof.rmse);
disp(result);

if options.OutputPrefix ~= ""
    folder = fileparts(options.OutputPrefix);
    if folder ~= "" && ~isfolder(folder); mkdir(folder); end
    writetable(struct2table(result), options.OutputPrefix + "_parameters.csv");
    writetable(table(x,y,feval(fitted,x), 'VariableNames', ...
        {'time_from_fit_start_s','observed_displacement_px','fitted_displacement_px'}), ...
        options.OutputPrefix + "_fit.csv");
    save(options.OutputPrefix + "_settings.mat", 'beam', 'options', 'input_file');
end
if options.ShowPlot
    figure; plot(x, y, '.', x, feval(fitted,x), '-');
    xlabel('Time from selected extremum (s)'); ylabel('Tip displacement (pixel)');
    legend('Observed','Damped harmonic fit'); grid on;
end
end
